import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;

public class VersionTagTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final String[] RAW = {
        "1.10.0", "1.2.3", "2.0.0", "1.2.3-beta", "1.9.9", "2.0.0-alpha", "1.2.3"
    };

    static List<VersionTag> parseAll() {
        List<VersionTag> list = new ArrayList<>();
        for (String raw : RAW) {
            list.add(VersionTag.parse(raw));
        }
        return list;
    }

    static String sortedText() {
        try {
            List<VersionTag> list = parseAll();
            Collections.sort(list);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) {
                    sb.append(",");
                }
                sb.append(String.valueOf(list.get(i)));
            }
            return sb.toString();
        } catch (RuntimeException e) {
            return "ERROR:" + e.getClass().getSimpleName();
        }
    }

    static String describe(String text) {
        try {
            return String.valueOf(VersionTag.parse(text));
        } catch (IllegalArgumentException e) {
            return "rejected";
        } catch (RuntimeException e) {
            return "wrong-exception:" + e.getClass().getSimpleName();
        }
    }

    static String sizeOf(Set<VersionTag> set) {
        try {
            set.addAll(parseAll());
            return String.valueOf(set.size());
        } catch (RuntimeException e) {
            return "ERROR:" + e.getClass().getSimpleName();
        }
    }

    static int sign(VersionTag a, VersionTag b) {
        try {
            return Integer.compare(a.compareTo(b), 0);
        } catch (RuntimeException e) {
            return -99;
        }
    }

    public static void main(String[] args) {
        check("toString round trip", "2.0.0-alpha", describe("2.0.0-alpha"));
        check("plain toString", "1.2.10", describe("1.2.10"));
        check("null is rejected", "rejected", describe(null));
        check("two parts is rejected", "rejected", describe("1.2"));
        check("letters are rejected", "rejected", describe("1.x.0"));
        check("empty suffix is rejected", "rejected", describe("1.0.0-"));

        try {
            VersionTag a = VersionTag.parse("1.10.0");
            VersionTag b = VersionTag.parse("1.9.9");
            check("1.10.0 beats 1.9.9 numerically", 1, sign(a, b));

            VersionTag pre = VersionTag.parse("1.2.3-beta");
            VersionTag rel = VersionTag.parse("1.2.3");
            check("a pre-release sorts first", -1, sign(pre, rel));
            check("and the release sorts after it", 1, sign(rel, pre));
            check("identical tags compare equal", 0, sign(rel, VersionTag.parse("1.2.3")));
            check("equals agrees with compareTo", true, rel.equals(VersionTag.parse("1.2.3")));
            check("equal tags share a hashCode", true,
                    rel.hashCode() == VersionTag.parse("1.2.3").hashCode());
            check("a pre-release is not equal to the release", false, rel.equals(pre));
            check("not equal to a String", false, rel.equals("1.2.3"));
        } catch (RuntimeException e) {
            System.out.println("FAIL  comparison checks -- expected none but got " + e);
            failures++;
        }

        check("full sort order",
                "1.2.3-beta,1.2.3,1.2.3,1.9.9,1.10.0,2.0.0-alpha,2.0.0",
                sortedText());
        check("TreeSet folds the duplicate", "6", sizeOf(new TreeSet<VersionTag>()));
        check("HashSet agrees with TreeSet", "6", sizeOf(new HashSet<VersionTag>()));

        try {
            check("latest", "2.0.0", String.valueOf(VersionTag.latest(parseAll())));
        } catch (RuntimeException e) {
            System.out.println("FAIL  latest -- expected none but got " + e);
            failures++;
        }
        check("latest of empty", "null", String.valueOf(VersionTag.latest(new ArrayList<VersionTag>())));
        check("latest of null", "null", String.valueOf(VersionTag.latest(null)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

