import java.util.List;
import java.util.Objects;

public class VersionTag implements Comparable<VersionTag> {

    private final int major;
    private final int minor;
    private final int patch;
    private final String preRelease;

    private VersionTag(int major, int minor, int patch, String preRelease) {
        this.major = major;
        this.minor = minor;
        this.patch = patch;
        this.preRelease = preRelease;
    }

    public static VersionTag parse(String text) {
        if (text == null) {
            throw new IllegalArgumentException("version text is null");
        }
        String core = text;
        String suffix = "";
        int dash = text.indexOf('-');
        if (dash >= 0) {
            core = text.substring(0, dash);
            suffix = text.substring(dash + 1);
            if (suffix.isEmpty()) {
                throw new IllegalArgumentException("empty pre-release in " + text);
            }
        }
        String[] parts = core.split("\\.", -1);
        if (parts.length != 3) {
            throw new IllegalArgumentException("need three parts in " + text);
        }
        int[] numbers = new int[3];
        for (int i = 0; i < 3; i++) {
            numbers[i] = parseNumber(parts[i], text);
        }
        return new VersionTag(numbers[0], numbers[1], numbers[2], suffix);
    }

    private static int parseNumber(String part, String whole) {
        if (part.isEmpty()) {
            throw new IllegalArgumentException("empty number in " + whole);
        }
        for (int i = 0; i < part.length(); i++) {
            if (!Character.isDigit(part.charAt(i))) {
                throw new IllegalArgumentException("not a number in " + whole);
            }
        }
        return Integer.parseInt(part);
    }

    public int getMajor() {
        return major;
    }

    public String getPreRelease() {
        return preRelease;
    }

    @Override
    public int compareTo(VersionTag other) {
        if (major != other.major) {
            return Integer.compare(major, other.major);
        }
        if (minor != other.minor) {
            return Integer.compare(minor, other.minor);
        }
        if (patch != other.patch) {
            return Integer.compare(patch, other.patch);
        }
        boolean mine = !preRelease.isEmpty();
        boolean theirs = !other.preRelease.isEmpty();
        if (mine && !theirs) {
            return -1;
        }
        if (!mine && theirs) {
            return 1;
        }
        return preRelease.compareTo(other.preRelease);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof VersionTag)) {
            return false;
        }
        return compareTo((VersionTag) other) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(major, minor, patch, preRelease);
    }

    @Override
    public String toString() {
        String base = major + "." + minor + "." + patch;
        if (preRelease.isEmpty()) {
            return base;
        }
        return base + "-" + preRelease;
    }

    public static VersionTag latest(List<VersionTag> tags) {
        if (tags == null || tags.isEmpty()) {
            return null;
        }
        VersionTag best = tags.get(0);
        for (VersionTag tag : tags) {
            if (tag.compareTo(best) > 0) {
                best = tag;
            }
        }
        return best;
    }
}
